// Accepts the gateway's daily totals and maps them to Zarin's reading shape:
//   { hotelId, meterId, type: 'electricity'|'water'|'gas', day: 'yyyy-MM-dd', value }
// Vendor-specific mapping lives here; the platform side never changes.
const allowed = new Set(['electricity', 'water', 'gas']);
const readings = [].concat($input.first().json.body.readings || []);
return readings
  .filter((r) => allowed.has(r.type) && /^\d{4}-\d{2}-\d{2}$/.test(r.day) && Number(r.value) >= 0)
  .map((r) => ({ json: {
    hotelId: r.hotelId,
    requestBody: { type: r.type, day: r.day, consumption: Number(r.value), meterId: r.meterId, source: 'smartMeter' },
  } }));

// Signs a request for the Zarin Integration API.
// With ZARIN_KEY_ID and ZARIN_KEY_SECRET set (a scoped key from `npm run integration-key`):
//   HMAC-SHA256(keySecret, `${timestamp}.${nonce}.${body}`), a fresh nonce per request (v2).
// Otherwise the shared secret: HMAC-SHA256(ZARIN_INTEGRATION_SECRET, `${timestamp}.${body}`) (v1).
// Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto on the n8n instance.
const crypto = require('crypto');
const keyId = $env.ZARIN_KEY_ID || '';
const keySecret = $env.ZARIN_KEY_SECRET || '';
const scoped = Boolean(keyId && keySecret);
return $input.all().map((item) => {
  const body = item.json.requestBody ? JSON.stringify(item.json.requestBody) : '';
  const timestamp = Math.floor(Date.now() / 1000);
  const nonce = scoped ? crypto.randomBytes(16).toString('hex') : '';
  const signature = crypto
    .createHmac('sha256', scoped ? keySecret : $env.ZARIN_INTEGRATION_SECRET)
    .update(scoped ? `${timestamp}.${nonce}.${body}` : `${timestamp}.${body}`)
    .digest('hex');
  return {
    json: {
      ...item.json,
      rawBody: body,
      zarinTimestamp: String(timestamp),
      zarinSignature: signature,
      zarinKeyId: scoped ? keyId : '',
      zarinNonce: nonce,
    },
  };
});
